#!/usr/bin/env python3
"""Copy the BlueBuzzah design system's generated files into this site.

  python3 scripts/sync_design_system.py          copy everything
  python3 scripts/sync_design_system.py --check  exit 1 and list files that differ (drift)

Run after the design system is re-imported. Never edit the copied files by hand.
"""
import pathlib, re, sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
DS = (ROOT / '../../.claude/skills/bluebuzzah-design-system').resolve()
LUCIDE_EXTRA = ROOT / 'scripts/lucide'  # lucide-static@1.55.0 glyphs the design system doesn't ship

ICONS = ['hand', 'usb', 'smartphone', 'info', 'triangle-alert', 'external-link', 'arrow-left', 'menu', 'download', 'check', 'settings', 'book']

COPIES = {  # repo path: design-system path
    'css/tokens.css': 'tokens.css',
    'css/bundle.css': 'components/bundle.css',
    'assets/bluebuzzah-mark-512.png': 'assets/Logos/bluebuzzah-mark-512.png',
    'favicon.ico': 'favicons/favicon.ico',
    **{f'assets/{n}': f'assets/Web/{n}' for n in [
        'favicon-16.png', 'favicon-32.png', 'favicon-48.png', 'apple-touch-icon-180.png',
        'icon-192.png', 'icon-512.png', 'icon-maskable-512.png']},
}


def sprite():
    out = ['<svg xmlns="http://www.w3.org/2000/svg">',
           '<!-- generated by scripts/sync_design_system.py; Lucide v1.55.0, ISC (scripts/lucide/LICENSE-lucide.txt) -->']
    for n in ICONS:
        src = DS / 'assets/Icons' / f'{n}.svg'
        if not src.exists():
            src = LUCIDE_EXTRA / f'{n}.svg'
        body = re.search(r'<svg[^>]*>(.*)</svg>', src.read_text(), re.S)[1]
        body = ''.join(line.strip() for line in body.splitlines())
        out.append(f'<symbol id="{n}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" '
                   f'stroke-linecap="round" stroke-linejoin="round">{body}</symbol>')
    return ('\n'.join(out) + '\n</svg>\n').encode()


def wanted():
    files = {dst: (DS / src).read_bytes() for dst, src in COPIES.items()}
    for f in sorted((DS / 'fonts').iterdir()):
        files[f'css/fonts/{f.name}'] = f.read_bytes()
    files['assets/icons.svg'] = sprite()
    return files


def main():
    if not DS.is_dir():
        print(f'Design system not found at {DS}.\nClone https://github.com/BlueBuzzah/BlueBuzzah-Workspace '
              'and run `npm run workspace:setup` so this repo sits under its projects/.', file=sys.stderr)
        sys.exit(2)
    check = '--check' in sys.argv
    drift = []
    for rel, data in wanted().items():
        path = ROOT / rel
        if path.exists() and path.read_bytes() == data:
            continue
        if check:
            drift.append(rel)
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(data)
            print(f'wrote {rel}')
    if drift:
        print('out of sync with the design system:\n  ' + '\n  '.join(drift))
        sys.exit(1)


if __name__ == '__main__':
    main()
